def generate_zpl(serial_num, batch_code):
    """Generate ZPL for automatic printing."""
    return f"""^XA
^FO50,50^A0N,50,50^FDLEDTECH LABEL^FS
^FO50,120^A0N,40,40^FDSerial No: {serial_num}^FS
^FO50,180^A0N,40,40^FDBatch Code: {batch_code}^FS
^FO50,240^BY3^BCN,100,Y,N,N^FD{serial_num}^FS
^XZ"""

